#include <limits>
#include <type_traits>

// Compile-time check using static const member
static_assert(std::numeric_limits<int>::is_integer, 
              "int must be integer");

template <typename T>
void check_precision() {
    // Accessing compile-time value
    constexpr int d = std::numeric_limits<T>::digits;
    // std::cout << d; // OK
}

int main() {
    // Function members are typically runtime evaluated
    float inf = std::numeric_limits<float>::infinity();
    // constexpr float inf_val = std::numeric_limits<float>::infinity(); // Error pre-C++20
}
